import pytest

SECONDS_PER_DAY: int = 86400


def stamp(ts: int) -> str:
    """Format a Unix timestamp (seconds) as UTC time-of-day 'HH:MM:SS'.

    Uses a 24-hour clock, zero-padded fields. The time of day is
    ts modulo SECONDS_PER_DAY, so values outside day 0 wrap around and
    negative timestamps map to the preceding time of day.
    """
    t: int = ts % SECONDS_PER_DAY
    hours: int = t // 3600
    minutes: int = (t % 3600) // 60
    seconds: int = t % 60
    return f"{hours:02d}:{minutes:02d}:{seconds:02d}"


def test_stamp_midnight() -> None:
    assert stamp(0) == "00:00:00"


def test_stamp_small_offset() -> None:
    assert stamp(3661) == "01:01:01"


def test_stamp_last_second_of_day() -> None:
    assert stamp(86399) == "23:59:59"


def test_stamp_wraps_at_day_boundary() -> None:
    assert stamp(86400) == "00:00:00"


def test_stamp_negative_wraps_to_previous_day() -> None:
    assert stamp(-1) == "23:59:59"


def test_stamp_large_value_is_zero_padded() -> None:
    assert stamp(9 * 3600 + 5 * 60 + 7) == "09:05:07"


def test_stamp_always_eight_chars() -> None:
    for ts in (0, 1, 59, 3600, 45296, 86399):
        assert len(stamp(ts)) == 8
